-- bq2 gate count HI-Medium 2022-09-01
SELECT CASE WHEN c.expected_pairs = c.actual_pairs AND c.expected_triples = c.actual_triples
   THEN 'true' ELSE 'false' END AS ok, c.*
FROM (
WITH
ta AS (
  SELECT txn_id, txn_ts, from_bank, from_account, to_bank, to_account,
         payment_format, payment_currency, receiving_currency, is_laundering,
         date_diff('day', DATE '2022-08-01', CAST(txn_date AS date)) AS day_idx
  FROM is459_g2t1_aml.transactions_clean
  WHERE dataset = 'HI-Medium' AND txn_date BETWEEN '2022-09-01' AND '2022-09-01'
),
tb AS (
  SELECT txn_id, txn_ts, from_bank, from_account, to_bank, to_account,
         payment_format, payment_currency, receiving_currency, is_laundering,
         date_diff('day', DATE '2022-08-01', CAST(txn_date AS date)) AS day_idx
  FROM is459_g2t1_aml.transactions_clean
  WHERE dataset = 'HI-Medium' AND txn_date BETWEEN '2022-09-01' AND '2022-09-02'
),
hop_a AS (
  SELECT ta.txn_id AS a_id, ta.txn_ts AS a_ts, ta.payment_format AS a_m, ta.payment_currency AS a_pc, ta.receiving_currency AS a_rc, ta.is_laundering AS a_l, ta.to_bank AS a_to_bank, ta.to_account AS a_to_account, ta.day_idx AS a_day FROM ta
),
pairs AS (
  SELECT h.*, tb.txn_id AS b_id, tb.txn_ts AS b_ts, tb.payment_format AS b_m, tb.payment_currency AS b_pc, tb.receiving_currency AS b_rc, tb.is_laundering AS b_l, tb.to_bank AS b_to_bank, tb.to_account AS b_to_account, tb.day_idx AS b_day
  FROM hop_a h
  CROSS JOIN UNNEST(ARRAY[h.a_day, h.a_day + 1]) AS k(key_day)
  JOIN tb ON tb.from_bank = h.a_to_bank AND tb.from_account = h.a_to_account AND tb.day_idx = k.key_day AND tb.txn_ts > h.a_ts AND tb.txn_ts <= h.a_ts + INTERVAL '1' DAY
  WHERE tb.txn_id <> h.a_id
),
tc AS (
  SELECT txn_id, txn_ts, from_bank, from_account, to_bank, to_account,
         payment_format, payment_currency, receiving_currency, is_laundering,
         date_diff('day', DATE '2022-08-01', CAST(txn_date AS date)) AS day_idx
  FROM is459_g2t1_aml.transactions_clean
  WHERE dataset = 'HI-Medium' AND txn_date BETWEEN '2022-09-01' AND '2022-09-03'
),
chains AS (
  SELECT p.*, tc.txn_id AS c_id, tc.txn_ts AS c_ts, tc.payment_format AS c_m, tc.payment_currency AS c_pc, tc.receiving_currency AS c_rc, tc.is_laundering AS c_l, tc.to_bank AS c_to_bank, tc.to_account AS c_to_account, tc.day_idx AS c_day
  FROM pairs p
  CROSS JOIN UNNEST(ARRAY[p.b_day, p.b_day + 1]) AS k(key_day)
  JOIN tc ON tc.from_bank = p.b_to_bank AND tc.from_account = p.b_to_account AND tc.day_idx = k.key_day AND tc.txn_ts > p.b_ts AND tc.txn_ts <= p.b_ts + INTERVAL '1' DAY
  WHERE tc.txn_id <> p.a_id AND tc.txn_id <> p.b_id
)
SELECT 'HI-Medium' AS dataset, '2022-09-01' AS start_date,
  (SELECT COUNT(*) FROM pairs) AS expected_pairs,
  (SELECT COUNT(*) FROM is459_g2t1_aml.bq2_sequences WHERE dataset = 'HI-Medium' AND start_date = '2022-09-01' AND sequence_length = 2) AS actual_pairs,
  (SELECT COUNT(*) FROM chains) AS expected_triples,
  (SELECT COUNT(*) FROM is459_g2t1_aml.bq2_sequences WHERE dataset = 'HI-Medium' AND start_date = '2022-09-01' AND sequence_length = 3) AS actual_triples
) c;

-- bq2 gate lineage HI-Medium 2022-09-01
SELECT CASE WHEN c.missing_members = 0 AND c.attribute_mismatches = 0
   AND c.broken_links = 0 THEN 'true' ELSE 'false' END AS ok, c.*
FROM (
WITH
src AS (
  SELECT txn_id, txn_ts, from_bank, from_account, to_bank, to_account, payment_format,
         payment_currency, receiving_currency, is_laundering
  FROM is459_g2t1_aml.transactions_clean WHERE dataset = 'HI-Medium' AND txn_date BETWEEN '2022-09-01' AND '2022-09-03'
),
m AS (
  SELECT u.id, u.pos, element_at(s.txn_ids, u.pos + 1) AS next_id,
         element_at(s.txn_timestamps, u.pos) AS ts, element_at(s.payment_methods, u.pos) AS pm,
         element_at(s.payment_currencies, u.pos) AS pc, element_at(s.receiving_currencies, u.pos) AS rc,
         element_at(s.txn_laundering_labels, u.pos) AS lbl
  FROM is459_g2t1_aml.bq2_sequences s CROSS JOIN UNNEST(s.txn_ids) WITH ORDINALITY AS u(id, pos)
  WHERE s.dataset = 'HI-Medium' AND s.start_date = '2022-09-01'
)
SELECT 'HI-Medium' AS dataset, '2022-09-01' AS start_date,
  COUNT(*) AS members_checked,
  coalesce(COUNT_IF(t.txn_id IS NULL), 0) AS missing_members,
  coalesce(COUNT_IF(t.txn_id IS NOT NULL AND NOT coalesce(t.txn_ts = m.ts AND t.payment_format = m.pm
      AND t.payment_currency = m.pc AND t.receiving_currency = m.rc AND t.is_laundering = m.lbl, false)), 0) AS attribute_mismatches,
  coalesce(COUNT_IF(m.next_id IS NOT NULL AND NOT coalesce(n.from_bank = t.to_bank AND n.from_account = t.to_account
      AND n.txn_ts > t.txn_ts AND n.txn_ts <= t.txn_ts + INTERVAL '1' DAY, false)), 0) AS broken_links
FROM m
LEFT JOIN src t ON t.txn_id = m.id
LEFT JOIN src n ON n.txn_id = m.next_id
) c;

